-- AlterEnum
ALTER TYPE "EntityTypes" ADD VALUE 'FDC';
ALTER TYPE "EntityTypes" ADD VALUE 'FRC';
ALTER TYPE "EntityTypes" ADD VALUE 'FNC';

-- Les anciens comptes FDC / FRC / FNC sont supprimés : les fédérations sont désormais des entités
DELETE FROM "User" WHERE "roles" && ARRAY['FDC', 'FRC', 'FNC']::"UserRoles"[] OR "role" IN ('FDC', 'FRC', 'FNC');

-- AlterEnum
BEGIN;
CREATE TYPE "UserRoles_new" AS ENUM ('ADMIN', 'CHASSEUR', 'COLLECTEUR_PRO', 'ETG', 'SVI', 'COMMERCE_DE_DETAIL', 'CANTINE_OU_RESTAURATION_COLLECTIVE', 'ASSOCIATION_CARITATIVE', 'REPAS_DE_CHASSE_OU_ASSOCIATIF', 'CONSOMMATEUR_FINAL', 'LABORATOIRE', 'FEDERATION');
ALTER TABLE "User" ALTER COLUMN "roles" TYPE "UserRoles_new"[] USING ("roles"::text::"UserRoles_new"[]);
ALTER TABLE "User" ALTER COLUMN "role" TYPE "UserRoles_new" USING ("role"::text::"UserRoles_new");
ALTER TYPE "UserRoles" RENAME TO "UserRoles_old";
ALTER TYPE "UserRoles_new" RENAME TO "UserRoles";
DROP TYPE "UserRoles_old";
COMMIT;

-- AlterTable
ALTER TABLE "Entity" ADD COLUMN     "scope_departements_codes" TEXT[];

-- AlterTable
ALTER TABLE "User" DROP COLUMN "scope_departements_codes";

-- Pré-création des fédérations : une FDC par département, une FRC par région, la FNC
ON CONFLICT ("id") DO NOTHING;
